 75	static uint32_t launcher_uptime_sec(void)
 76	{
 77	  struct timespec ts;
 78	
 79	  clock_gettime(CLOCK_MONOTONIC, &ts);
 80	  return (uint32_t)ts.tv_sec;
 81	}
