 83	static void launcher_format_clock(char *buf, size_t buflen, uint32_t sec)
 84	{
 85	  snprintf(buf, buflen, "%02u:%02u:%02u",
 86	           (sec / 3600) % 100, (sec / 60) % 60, sec % 60);
 87	}
