122	static void launcher_lock_swipe_event_cb(lv_event_t *e)
123	{
124	  lv_event_code_t code = lv_event_get_code(e);
125	  lv_indev_t *indev = lv_indev_active();
126	  lv_point_t p;
127	
128	  if (indev == NULL)
129	    {
130	      return;
131	    }
132	
133	  lv_indev_get_point(indev, &p);
134	
135	  if (code == LV_EVENT_PRESSED)
136	    {
137	      g_drag_start = p;
138	    }
139	  else if (code == LV_EVENT_PRESSING)
140	    {
141	      if (g_drag_start.y - p.y > UNLOCK_DRAG_DIST)
142	        {
143	          lv_indev_wait_release(indev);
144	          launcher_unlock();
145	        }
146	    }
147	}
