249	
250	static void launcher_paint_dot(int32_t x, int32_t y)
251	{
252	  int32_t dx;
253	  int32_t dy;
254	
255	  for (dy = -PAINT_BRUSH_RADIUS; dy <= PAINT_BRUSH_RADIUS; dy++)
256	    {
257	      for (dx = -PAINT_BRUSH_RADIUS; dx <= PAINT_BRUSH_RADIUS; dx++)
258	        {
259	          if (dx * dx + dy * dy <=
260	              PAINT_BRUSH_RADIUS * PAINT_BRUSH_RADIUS &&
261	              x + dx >= 0 && x + dx < LAUNCHER_SCREEN_W &&
262	              y + dy >= 0 && y + dy < LAUNCHER_SCREEN_H)
263	            {
264	              g_canvas_buf[(y + dy) * LAUNCHER_SCREEN_W + x + dx] =
265	                g_brush_color;
266	            }
267	        }
268	    }
269	}
270	
271	static void launcher_paint_stroke(int32_t x0, int32_t y0,
272	                                  int32_t x1, int32_t y1)
273	{
274	  int32_t dx = x1 - x0;
275	  int32_t dy = y1 - y0;
276	  int32_t steps = LV_MAX(LV_ABS(dx), LV_ABS(dy));
277	  int32_t i;
278	
279	  if (steps == 0)
280	    {
281	      launcher_paint_dot(x1, y1);
282	      return;
283	    }
284	
285	  for (i = 0; i <= steps; i += PAINT_STROKE_STEP)
286	    {
287	      launcher_paint_dot(x0 + dx * i / steps, y0 + dy * i / steps);
288	    }
289	}
290	
291	static void launcher_paint_invalidate(int32_t x0, int32_t y0,
292	                                      int32_t x1, int32_t y1)
293	{
294	  lv_area_t area =
295	    {
296	      LV_MIN(x0, x1) - PAINT_BRUSH_RADIUS - 2,
297	      LV_MIN(y0, y1) - PAINT_BRUSH_RADIUS - 2,
298	      LV_MAX(x0, x1) + PAINT_BRUSH_RADIUS + 2,
299	      LV_MAX(y0, y1) + PAINT_BRUSH_RADIUS + 2
300	    };
301	
302	  lv_obj_invalidate_area(g_canvas, &area);
303	}
