305	static void launcher_canvas_event_cb(lv_event_t *e)
306	{
307	  lv_event_code_t code = lv_event_get_code(e);
308	  lv_indev_t *indev = lv_indev_active();
309	  lv_point_t p;
310	
311	  if (indev == NULL)
312	    {
313	      return;
314	    }
315	
316	  lv_indev_get_point(indev, &p);
317	
318	  if (code == LV_EVENT_PRESSED)
319	    {
