321	    }
322	
323	  launcher_paint_stroke(g_brush_prev.x, g_brush_prev.y, p.x, p.y);
324	  launcher_paint_invalidate(g_brush_prev.x, g_brush_prev.y, p.x, p.y);
325	  g_brush_prev = p;
326	}
