357	{
358	  lv_obj_t *scr;
359	  lv_obj_t *obj;
360	  int i;
361	
362	  g_canvas_buf = memalign(64, CANVAS_BUF_SIZE);
363	  if (g_canvas_buf == NULL)
364	    {
365	      fprintf(stderr, "launcher: canvas alloc failed\n");
366	      return false;
367	    }
368	
369	  scr = lv_obj_create(NULL);
370	  lv_obj_set_style_bg_color(scr, lv_color_hex(0xffffff), 0);
371	
372	  g_canvas = lv_canvas_create(scr);
373	  lv_canvas_set_buffer(g_canvas, g_canvas_buf, LAUNCHER_SCREEN_W,
374	                       LAUNCHER_SCREEN_H, LV_COLOR_FORMAT_RGB565);
375	  lv_canvas_fill_bg(g_canvas, lv_color_hex(0xffffff), LV_OPA_COVER);
376	  lv_obj_add_flag(g_canvas, LV_OBJ_FLAG_CLICKABLE);
377	  lv_obj_add_event_cb(g_canvas, launcher_canvas_event_cb, LV_EVENT_PRESSED,
378	                      NULL);
379	  lv_obj_add_event_cb(g_canvas, launcher_canvas_event_cb, LV_EVENT_PRESSING,
