382	  obj = lv_obj_create(scr);
383	  lv_obj_set_size(obj, LAUNCHER_SCREEN_W, 120);
384	  lv_obj_set_style_bg_color(obj, lv_color_hex(LAUNCHER_CARD_COLOR), 0);
385	  lv_obj_set_style_bg_opa(obj, LV_OPA_90, 0);
386	  lv_obj_set_style_border_width(obj, 0, 0);
387	  lv_obj_set_scrollbar_mode(obj, LV_SCROLLBAR_MODE_OFF);
388	  lv_obj_clear_flag(obj, LV_OBJ_FLAG_SCROLLABLE);
389	  lv_obj_align(obj, LV_ALIGN_TOP_MID, 0, 0);
390	
391	  obj = lv_button_create(scr);
392	  lv_obj_set_size(obj, 200, 70);
393	  lv_obj_set_style_radius(obj, 24, 0);
394	  lv_obj_align(obj, LV_ALIGN_TOP_LEFT, 40, 25);
395	  lv_obj_add_event_cb(obj, launcher_back_event_cb, LV_EVENT_CLICKED, NULL);
396	
397	  launcher_label(obj, LV_SYMBOL_LEFT " Back", &lv_font_montserrat_16,
398	                 0xffffff, LV_ALIGN_CENTER, 0, 0);
399	
400	  obj = lv_button_create(scr);
401	  lv_obj_set_size(obj, 200, 70);
402	  lv_obj_set_style_radius(obj, 24, 0);
403	  lv_obj_align(obj, LV_ALIGN_TOP_RIGHT, -40, 25);
404	  lv_obj_add_event_cb(obj, launcher_paint_clear_cb, LV_EVENT_CLICKED,
