476	static void launcher_periodic_cb(lv_timer_t *timer)
477	{
478	  char buf[32];
479	  struct mallinfo mi = mallinfo();
480	  uint32_t sec = launcher_uptime_sec();
481	  uint32_t fps = g_refr_count;
482	
483	  UNUSED(timer);
484	
485	  g_refr_count = 0;
486	  launcher_format_clock(buf, sizeof(buf), sec);
487	
488	  if (lv_screen_active() == g_lock_scr)
489	    {
490	      lv_label_set_text(g_lock_clock, buf);
491	    }
492	  else if (lv_screen_active() == g_home_scr)
493	    {
494	      lv_label_set_text(g_home_clock, buf);
495	      lv_label_set_text_fmt(g_home_uptime, "up %us - heap %uKB free",
496	                            sec, mi.fordblks / 1024);
497	    }
498	
499	  lv_label_set_text_fmt(g_about_fps, "fps: %u", fps);
500	  lv_label_set_text_fmt(g_about_heap, "heap: %uKB free", mi.fordblks / 1024);
501	  lv_label_set_text_fmt(g_home_fps, "%u fps", fps);
502	}
