508	int main(int argc, FAR char *argv[])
509	{
510	  lv_nuttx_dsc_t info;
511	  lv_nuttx_result_t result;
512	
513	  UNUSED(argc);
514	  UNUSED(argv);
515	
516	  lv_init();
517	
518	  lv_nuttx_dsc_init(&info);
519	  info.input_path = TOUCH_DEVPATH;
520	  lv_nuttx_init(&info, &result);
521	
522	  if (result.disp == NULL)
523	    {
524	      fprintf(stderr, "launcher: no display found\n");
525	      return 1;
526	    }
527	
528	  if (result.indev == NULL)
529	    {
530	      fprintf(stderr, "launcher: no touchscreen found\n");
531	      return 1;
532	    }
533	
534	  lv_display_add_event_cb(result.disp, launcher_refr_event_cb,
535	                          LV_EVENT_REFR_START, NULL);
536	
537	  launcher_create_about_scr();
538	  if (!launcher_create_paint_scr())
539	    {
540	      return 1;
541	    }
542	
543	  launcher_create_home_scr();
544	  launcher_create_lock_scr();
545	
