/****************************************************************************
 * app/launcher/launcher_main.c
 *
 * Contest 2026 team 349 (FedoraVForce) LVGL launcher
 * VSAI LogicPi A1 (Amlogic S6): MIPI DSI 1080x1920 + GT9XX touch
 *
 * Apps are NSH builtins listed in CONFIG_LVX_CONTEST2026_349_LAUNCHER_APPS.
 * LVGL is a single global instance, so the launcher releases it before
 * starting an app and initializes it again after the app exits.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/param.h>
#include <sys/wait.h>

#include <ctype.h>
#include <errno.h>
#include <malloc.h>
#include <sched.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <nuttx/lib/builtin.h>

#include <lvgl/lvgl.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define LAUNCHER_SCREEN_W     1080
#define LAUNCHER_SCREEN_H     1920

#define LAUNCHER_BG_TOP       0x16243a
#define LAUNCHER_BG_BOTTOM    0x080d16
#define LAUNCHER_CARD_COLOR   0x1c2b42
#define LAUNCHER_CARD_PRESSED 0x2a3d5a
#define LAUNCHER_ACCENT       0x00a8f3
#define LAUNCHER_TEXT_DIM     0x8fa3bf

#define LAUNCHER_ICON_SIZE    180
#define LAUNCHER_ICON_RADIUS  52
#define LAUNCHER_ANIM_TIME    300
#define LAUNCHER_ZOOM_MAX     1024
#define UNLOCK_DRAG_DIST      300

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_nuttx_result_t g_result;

static lv_obj_t *g_lock_scr;
static lv_obj_t *g_lock_body;
static lv_obj_t *g_home_scr;
static lv_obj_t *g_home_card;
static lv_obj_t *g_home_grid;
static lv_obj_t *g_about_scr;

static lv_obj_t *g_lock_clock;
static lv_obj_t *g_home_clock;
static lv_obj_t *g_home_info;
static lv_obj_t *g_about_uptime;
static lv_obj_t *g_about_heap;

static lv_obj_t *g_return_icon;
static lv_area_t g_zoom_area;
static int32_t g_drag_start;
static int g_launch;

static const uint32_t g_icon_colors[][2] =
{
  { 0x36d1dc, 0x5b86e5 },
  { 0xff7a59, 0xff3d6e },
  { 0x8e7bff, 0x5f3dc4 },
  { 0x4ade80, 0x0ea5a4 },
  { 0xfbbf24, 0xf97316 },
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static lv_obj_t *launcher_label(lv_obj_t *parent, const char *text,
                                const lv_font_t *font, uint32_t color,
                                lv_align_t align, int32_t x, int32_t y)
{
  lv_obj_t *label = lv_label_create(parent);

  lv_obj_set_style_text_font(label, font, 0);
  lv_obj_set_style_text_color(label, lv_color_hex(color), 0);
  lv_label_set_text(label, text);
  lv_obj_align(label, align, x, y);
  return label;
}

static lv_obj_t *launcher_box(lv_obj_t *parent, uint32_t color,
                              int32_t radius)
{
  lv_obj_t *obj = lv_obj_create(parent);

  lv_obj_remove_style_all(obj);
  lv_obj_remove_flag(obj, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_set_style_bg_color(obj, lv_color_hex(color), 0);
  lv_obj_set_style_bg_opa(obj, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(obj, radius, 0);
  return obj;
}

static lv_obj_t *launcher_screen(void)
{
  lv_obj_t *scr = lv_obj_create(NULL);

  lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_set_style_bg_color(scr, lv_color_hex(LAUNCHER_BG_TOP), 0);
  lv_obj_set_style_bg_grad_color(scr, lv_color_hex(LAUNCHER_BG_BOTTOM), 0);
  lv_obj_set_style_bg_grad_dir(scr, LV_GRAD_DIR_VER, 0);
  return scr;
}

/* Montserrat stops at 48px, so the clocks are drawn at twice that size */

static void launcher_zoom_label(lv_obj_t *label)
{
  lv_obj_set_style_transform_scale(label, 2 * LV_SCALE_NONE, 0);
  lv_obj_set_style_transform_pivot_x(label, lv_pct(50), 0);
  lv_obj_set_style_transform_pivot_y(label, lv_pct(50), 0);
}

static void launcher_anim(void *var, lv_anim_exec_xcb_t exec_cb,
                          int32_t from, int32_t to, uint32_t delay,
                          lv_anim_path_cb_t path_cb,
                          lv_anim_completed_cb_t completed_cb)
{
  lv_anim_t a;

  lv_anim_init(&a);
  lv_anim_set_var(&a, var);
  lv_anim_set_exec_cb(&a, exec_cb);
  lv_anim_set_values(&a, from, to);
  lv_anim_set_duration(&a, LAUNCHER_ANIM_TIME);
  lv_anim_set_delay(&a, delay);
  lv_anim_set_path_cb(&a, path_cb);
  lv_anim_set_completed_cb(&a, completed_cb);
  lv_anim_start(&a);
}

static void launcher_translate_y_cb(void *obj, int32_t v)
{
  lv_obj_set_style_translate_y(obj, v, 0);
}

static void launcher_info_row(lv_obj_t *parent, const char *key,
                              const char *val, lv_obj_t **val_label)
{
  lv_obj_t *row = lv_obj_create(parent);
  lv_obj_t *label;

  lv_obj_remove_style_all(row);
  lv_obj_set_size(row, lv_pct(100), LV_SIZE_CONTENT);
  lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  launcher_label(row, key, &lv_font_montserrat_24, LAUNCHER_TEXT_DIM,
                 LV_ALIGN_DEFAULT, 0, 0);
  label = launcher_label(row, val, &lv_font_montserrat_24, 0xffffff,
                         LV_ALIGN_DEFAULT, 0, 0);
  if (val_label != NULL)
    {
      *val_label = label;
    }
}

static lv_obj_t *launcher_card(lv_obj_t *parent, const char *title)
{
  lv_obj_t *card = launcher_box(parent, LAUNCHER_CARD_COLOR, 40);

  lv_obj_set_size(card, lv_pct(100), LV_SIZE_CONTENT);
  lv_obj_set_style_pad_all(card, 48, 0);
  lv_obj_set_style_pad_row(card, 32, 0);
  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);

  launcher_label(card, title, &lv_font_montserrat_24, LAUNCHER_ACCENT,
                 LV_ALIGN_DEFAULT, 0, 0);
  return card;
}

/****************************************************************************
 * Name: app icons
 ****************************************************************************/

static lv_obj_t *launcher_icon(lv_obj_t *parent, int index)
{
  FAR const char *name = builtin_getname(index);
  const uint32_t *c = g_icon_colors[index % nitems(g_icon_colors)];
  lv_obj_t *icon = launcher_box(parent, c[0], LAUNCHER_ICON_RADIUS);
  lv_obj_t *label;

  lv_obj_set_size(icon, LAUNCHER_ICON_SIZE, LAUNCHER_ICON_SIZE);
  lv_obj_set_style_bg_grad_color(icon, lv_color_hex(c[1]), 0);
  lv_obj_set_style_bg_grad_dir(icon, LV_GRAD_DIR_VER, 0);

  label = launcher_label(icon, "", &lv_font_montserrat_48, 0xffffff,
                         LV_ALIGN_CENTER, 0, 0);
  lv_label_set_text_fmt(label, "%c", toupper(name[0]));
  return icon;
}

/* Grow or shrink a top layer icon between g_zoom_area and full screen */

static void launcher_zoom_cb(void *obj, int32_t v)
{
  lv_area_t *a = &g_zoom_area;

  lv_obj_set_pos(obj, lv_map(v, 0, LAUNCHER_ZOOM_MAX, a->x1, 0),
                 lv_map(v, 0, LAUNCHER_ZOOM_MAX, a->y1, 0));
  lv_obj_set_size(obj,
                  lv_map(v, 0, LAUNCHER_ZOOM_MAX, lv_area_get_width(a),
                         LAUNCHER_SCREEN_W),
                  lv_map(v, 0, LAUNCHER_ZOOM_MAX, lv_area_get_height(a),
                         LAUNCHER_SCREEN_H));
  lv_obj_set_style_radius(obj, lv_map(v, 0, LAUNCHER_ZOOM_MAX,
                                      LAUNCHER_ICON_RADIUS, 0), 0);
}

static void launcher_zoomed_cb(lv_anim_t *a)
{
  g_launch = (int)(intptr_t)lv_obj_get_user_data(a->var);
}

static void launcher_app_event_cb(lv_event_t *e)
{
  int index = (int)(intptr_t)lv_event_get_user_data(e);
  lv_obj_t *obj = launcher_icon(lv_layer_top(), index);

  lv_obj_set_user_data(obj, (void *)(intptr_t)index);
  lv_obj_get_coords(lv_event_get_target(e), &g_zoom_area);
  launcher_anim(obj, launcher_zoom_cb, 0, LAUNCHER_ZOOM_MAX, 0,
                lv_anim_path_ease_in_out, launcher_zoomed_cb);
}

static void launcher_app_tile(lv_obj_t *parent, int index, int last)
{
  FAR const char *name = builtin_getname(index);
  lv_obj_t *tile = lv_obj_create(parent);
  lv_obj_t *icon;
  lv_obj_t *label;

  lv_obj_remove_style_all(tile);
  lv_obj_set_size(tile, lv_pct(25), LV_SIZE_CONTENT);
  lv_obj_set_flex_flow(tile, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(tile, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                        LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_row(tile, 20, 0);

  icon = launcher_icon(tile, index);
  lv_obj_set_style_transform_width(icon, -10, LV_STATE_PRESSED);
  lv_obj_set_style_transform_height(icon, -10, LV_STATE_PRESSED);
  lv_obj_add_event_cb(icon, launcher_app_event_cb, LV_EVENT_CLICKED,
                      (void *)(intptr_t)index);

  label = launcher_label(tile, "", &lv_font_montserrat_24, 0xffffff,
                         LV_ALIGN_DEFAULT, 0, 0);
  lv_label_set_text_fmt(label, "%c%s", toupper(name[0]), name + 1);

  if (index == last)
    {
      g_return_icon = icon;
    }
}

static void launcher_create_apps(lv_obj_t *parent, int last)
{
  char list[] = CONFIG_LVX_CONTEST2026_349_LAUNCHER_APPS;
  FAR char *save;
  FAR char *name;
  int count = 0;
  int index;

  for (name = strtok_r(list, " ", &save); name != NULL;
       name = strtok_r(NULL, " ", &save))
    {
      index = builtin_isavail(name);
      if (index >= 0)
        {
          launcher_app_tile(parent, index, last);
          count++;
        }
    }

  if (count == 0)
    {
      launcher_label(parent, "No apps installed", &lv_font_montserrat_24,
                     LAUNCHER_TEXT_DIM, LV_ALIGN_DEFAULT, 0, 0);
    }
}

/****************************************************************************
 * Name: about screen
 ****************************************************************************/

static void launcher_about_close_cb(lv_event_t *e)
{
  UNUSED(e);
  lv_screen_load_anim(g_home_scr, LV_SCR_LOAD_ANIM_MOVE_RIGHT,
                      LAUNCHER_ANIM_TIME, 0, false);
}

static void launcher_create_about_scr(void)
{
  lv_obj_t *scr = launcher_screen();
  lv_obj_t *body;
  lv_obj_t *card;
  lv_obj_t *obj;

  obj = launcher_box(scr, LAUNCHER_CARD_COLOR, LV_RADIUS_CIRCLE);
