                            LV_STATE_PRESSED);
  lv_obj_align(obj, LV_ALIGN_TOP_LEFT, 60, 60);
  lv_obj_add_event_cb(obj, launcher_about_close_cb, LV_EVENT_CLICKED, NULL);
  launcher_label(obj, LV_SYMBOL_LEFT, &lv_font_montserrat_24, 0xffffff,
                 LV_ALIGN_CENTER, 0, 0);

  launcher_label(scr, "System", &lv_font_montserrat_48, 0xffffff,
                 LV_ALIGN_TOP_LEFT, 210, 86);

  body = lv_obj_create(scr);
  lv_obj_remove_style_all(body);
  lv_obj_set_size(body, 960, LV_SIZE_CONTENT);
  lv_obj_set_flex_flow(body, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_style_pad_row(body, 40, 0);
  lv_obj_align(body, LV_ALIGN_TOP_MID, 0, 230);

  card = launcher_card(body, "HARDWARE");
  launcher_info_row(card, "Board", "VSAI LogicPi A1", NULL);
  launcher_info_row(card, "SoC", "Amlogic S6 (ARM64)", NULL);
  launcher_info_row(card, "Interrupt", "GICv3", NULL);
  launcher_info_row(card, "Display", "MIPI DSI 1080x1920", NULL);
  launcher_info_row(card, "Touch", "GT9XX I2C", NULL);

  card = launcher_card(body, "SOFTWARE");
  launcher_info_row(card, "OS", "NuttX / openvela", NULL);
  launcher_info_row(card, "Graphics",
                    "LVGL " LV_STRINGIFY(LVGL_VERSION_MAJOR) "."
                    LV_STRINGIFY(LVGL_VERSION_MINOR), NULL);
  launcher_info_row(card, "Uptime", "-", &g_about_uptime);
  launcher_info_row(card, "Free heap", "-", &g_about_heap);

  g_about_scr = scr;
}

/****************************************************************************
 * Name: home screen
 ****************************************************************************/

static void launcher_about_open_cb(lv_event_t *e)
{
  UNUSED(e);
  lv_screen_load_anim(g_about_scr, LV_SCR_LOAD_ANIM_MOVE_LEFT,
                      LAUNCHER_ANIM_TIME, 0, false);
}

static void launcher_create_home_scr(int last)
{
  lv_obj_t *scr = launcher_screen();

  launcher_label(scr, "FedoraVForce", &lv_font_montserrat_24,
                 LAUNCHER_TEXT_DIM, LV_ALIGN_TOP_LEFT, 60, 60);
  launcher_label(scr, "openvela", &lv_font_montserrat_24,
                 LAUNCHER_TEXT_DIM, LV_ALIGN_TOP_RIGHT, -60, 60);

  g_home_card = launcher_box(scr, LAUNCHER_CARD_COLOR, 48);
  lv_obj_set_size(g_home_card, 960, 400);
  lv_obj_set_style_bg_color(g_home_card,
                            lv_color_hex(LAUNCHER_CARD_PRESSED),
                            LV_STATE_PRESSED);
  lv_obj_align(g_home_card, LV_ALIGN_TOP_MID, 0, 140);
  lv_obj_add_event_cb(g_home_card, launcher_about_open_cb, LV_EVENT_CLICKED,
                      NULL);

  g_home_clock = launcher_label(g_home_card, "00:00:00",
                                &lv_font_montserrat_48, 0xffffff,
                                LV_ALIGN_CENTER, 0, -60);
  launcher_zoom_label(g_home_clock);
  g_home_info = launcher_label(g_home_card, "-", &lv_font_montserrat_24,
                               LAUNCHER_TEXT_DIM, LV_ALIGN_CENTER, 0, 70);
  launcher_label(g_home_card, "System info " LV_SYMBOL_RIGHT,
                 &lv_font_montserrat_16, LAUNCHER_ACCENT,
                 LV_ALIGN_BOTTOM_RIGHT, -40, -32);

  launcher_label(scr, "Apps", &lv_font_montserrat_24, LAUNCHER_TEXT_DIM,
                 LV_ALIGN_TOP_LEFT, 60, 610);

  g_home_grid = lv_obj_create(scr);
  lv_obj_remove_style_all(g_home_grid);
  lv_obj_set_size(g_home_grid, 960, LV_SIZE_CONTENT);
  lv_obj_set_flex_flow(g_home_grid, LV_FLEX_FLOW_ROW_WRAP);
  lv_obj_set_style_pad_row(g_home_grid, 48, 0);
  lv_obj_align(g_home_grid, LV_ALIGN_TOP_MID, 0, 680);
  launcher_create_apps(g_home_grid, last);

  g_home_scr = scr;
}

static void launcher_home_intro(void)
{
  uint32_t i;

  launcher_anim(g_home_card, launcher_translate_y_cb, -200, 0, 0,
                lv_anim_path_ease_out, NULL);

  for (i = 0; i < lv_obj_get_child_count(g_home_grid); i++)
    {
      launcher_anim(lv_obj_get_child(g_home_grid, i),
                    launcher_translate_y_cb, 600, 0, 60 + i * 50,
                    lv_anim_path_overshoot, NULL);
    }
}

/****************************************************************************
 * Name: lock screen
 ****************************************************************************/

static void launcher_unlocked_cb(lv_anim_t *a)
{
  UNUSED(a);
  lv_screen_load(g_home_scr);
  launcher_home_intro();
}

static void launcher_unlock(void)
{
  launcher_anim(g_lock_body, launcher_translate_y_cb,
                lv_obj_get_style_translate_y(g_lock_body, 0),
                -LAUNCHER_SCREEN_H, 0, lv_anim_path_ease_in,
                launcher_unlocked_cb);
}

static void launcher_lock_event_cb(lv_event_t *e)
{
  lv_event_code_t code = lv_event_get_code(e);
  lv_point_t p;
  int32_t dy;

  lv_indev_get_point(lv_indev_active(), &p);
  dy = MAX(g_drag_start - p.y, 0);

  if (code == LV_EVENT_PRESSED)
    {
      g_drag_start = p.y;
    }
  else if (code == LV_EVENT_PRESSING)
    {
      lv_obj_set_style_translate_y(g_lock_body, -dy, 0);
    }
  else if (dy > UNLOCK_DRAG_DIST)
    {
      launcher_unlock();
    }
  else
    {
      launcher_anim(g_lock_body, launcher_translate_y_cb, -dy, 0, 0,
                    lv_anim_path_overshoot, NULL);
    }
}

static void launcher_unlock_event_cb(lv_event_t *e)
{
  UNUSED(e);
  launcher_unlock();
}

static void launcher_create_lock_scr(void)
{
  lv_obj_t *scr = launcher_screen();
  lv_obj_t *body;
  lv_obj_t *obj;
  lv_anim_t a;

  body = lv_obj_create(scr);
  lv_obj_remove_style_all(body);
  lv_obj_remove_flag(body, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_add_flag(body, LV_OBJ_FLAG_PRESS_LOCK);
  lv_obj_set_size(body, lv_pct(100), lv_pct(100));
  lv_obj_add_event_cb(body, launcher_lock_event_cb, LV_EVENT_PRESSED, NULL);
  lv_obj_add_event_cb(body, launcher_lock_event_cb, LV_EVENT_PRESSING,
                      NULL);
  lv_obj_add_event_cb(body, launcher_lock_event_cb, LV_EVENT_RELEASED,
                      NULL);

  g_lock_clock = launcher_label(body, "00:00:00", &lv_font_montserrat_48,
                                0xffffff, LV_ALIGN_CENTER, 0, -420);
  launcher_zoom_label(g_lock_clock);
  launcher_label(body, "openvela on LogicPi A1", &lv_font_montserrat_24,
                 LAUNCHER_TEXT_DIM, LV_ALIGN_CENTER, 0, -300);

  obj = launcher_box(body, LAUNCHER_ACCENT, LV_RADIUS_CIRCLE);
  lv_obj_set_size(obj, 160, 160);
  lv_obj_add_flag(obj, LV_OBJ_FLAG_EVENT_BUBBLE);
  lv_obj_align(obj, LV_ALIGN_BOTTOM_MID, 0, -300);
  lv_obj_add_event_cb(obj, launcher_unlock_event_cb, LV_EVENT_SHORT_CLICKED,
                      NULL);

  obj = launcher_label(obj, LV_SYMBOL_UP, &lv_font_montserrat_48,
                       LAUNCHER_BG_BOTTOM, LV_ALIGN_CENTER, 0, 0);

  lv_anim_init(&a);
  lv_anim_set_var(&a, obj);
  lv_anim_set_exec_cb(&a, launcher_translate_y_cb);
  lv_anim_set_values(&a, 8, -12);
  lv_anim_set_duration(&a, 600);
  lv_anim_set_playback_duration(&a, 600);
  lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
  lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
  lv_anim_start(&a);

  launcher_label(body, "Swipe up to unlock", &lv_font_montserrat_24,
                 LAUNCHER_TEXT_DIM, LV_ALIGN_BOTTOM_MID, 0, -180);

  g_lock_body = body;
  g_lock_scr = scr;
}

/****************************************************************************
 * Name: lifecycle
 ****************************************************************************/

static void launcher_periodic_cb(lv_timer_t *timer)
{
  struct mallinfo mi = mallinfo();
  struct timespec ts;
  uint32_t sec;

  UNUSED(timer);

  clock_gettime(CLOCK_MONOTONIC, &ts);
  sec = ts.tv_sec;

  lv_label_set_text_fmt(g_lock_clock, "%02" PRIu32 ":%02" PRIu32
                        ":%02" PRIu32, (sec / 3600) % 100,
                        (sec / 60) % 60, sec % 60);
  lv_label_set_text(g_home_clock, lv_label_get_text(g_lock_clock));
  lv_label_set_text_fmt(g_home_info, "up %" PRIu32 "s - %dKB free",
                        sec, mi.fordblks / 1024);
  lv_label_set_text_fmt(g_about_uptime, "%" PRIu32 " s", sec);
  lv_label_set_text_fmt(g_about_heap, "%d KB", mi.fordblks / 1024);
}

/* "last" is the app that just exited, or -1 on boot */

static int launcher_start(int last)
{
  lv_nuttx_dsc_t info;
  lv_obj_t *obj;

  lv_init();

  lv_nuttx_dsc_init(&info);
  lv_nuttx_init(&info, &g_result);

  if (g_result.disp == NULL || g_result.indev == NULL)
    {
      fprintf(stderr, "launcher: no display or touchscreen\n");
      return -ENODEV;
    }

  launcher_create_about_scr();
  launcher_create_home_scr(last);
  launcher_create_lock_scr();

  launcher_periodic_cb(NULL);
  lv_timer_create(launcher_periodic_cb, 1000, NULL);

  if (last < 0)
    {
      lv_screen_load(g_lock_scr);
      return 0;
    }

  /* Shrink the app back into its icon */

  lv_screen_load(g_home_scr);
  lv_obj_update_layout(g_home_scr);
  lv_obj_get_coords(g_return_icon, &g_zoom_area);

  obj = launcher_icon(lv_layer_top(), last);
  launcher_zoom_cb(obj, LAUNCHER_ZOOM_MAX);
  launcher_anim(obj, launcher_zoom_cb, LAUNCHER_ZOOM_MAX, 0, 0,
                lv_anim_path_ease_in_out, lv_obj_delete_anim_completed_cb);
  return 0;
}

static void launcher_stop(void)
{
  lv_nuttx_deinit(&g_result);
  lv_deinit();
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  FAR const struct builtin_s *app;
  uint32_t idle;
  int last = -1;
  pid_t pid;

  UNUSED(argc);
  UNUSED(argv);

  while (launcher_start(last) == 0)
    {
      g_launch = -1;
      while (g_launch < 0)
        {
          idle = lv_timer_handler();
          usleep(MAX(idle, 1) * 1000);
        }

      /* Keep the zoomed icon on screen while the app starts */

      lv_refr_now(NULL);
      launcher_stop();

      last = g_launch;
      app = builtin_for_index(last);
      pid = task_create(app->name, app->priority, app->stacksize, app->main,
                        NULL);
      if (pid < 0)
        {
          fprintf(stderr, "launcher: start %s failed: %d\n", app->name,
                  errno);
        }
      else
        {
          waitpid(pid, NULL, 0);
        }
    }

  launcher_stop();
  return 1;
}

