  obj = launcher_box(scr, LAUNCHER_LIVE_COLOR, LV_RADIUS_CIRCLE);
  lv_obj_set_size(obj, 84, 84);
  lv_obj_align(obj, LV_ALIGN_TOP_RIGHT, -LAUNCHER_MARGIN, 64);
  launcher_label(obj, "FV", &lv_font_montserrat_24, 0xffffff,
                 LV_ALIGN_CENTER, 0, 0);
